def _run_embedded_step(filename: str, b64_source: str, flask_app) -> None:
    """Fuehrt ein eingebettetes Alt-Skript mit bestehendem App-Context aus."""
    import app as app_package

    source = base64.b64decode(b64_source).decode("utf-8")

    original_create_app = app_package.create_app

    def _fake_create_app(*_args, **_kwargs):
        return flask_app

    # VOR exec patchen, damit "from app import create_app" die Fake-Funktion bekommt
    app_package.create_app = _fake_create_app
    try:
        namespace = {
            "__name__": "_embedded_" + filename.replace(".", "_"),
            "__file__": os.path.join(os.path.dirname(__file__), filename),
        }
        exec(compile(source, filename, "exec"), namespace)

        if "migrate" in namespace and callable(namespace["migrate"]):
            result = namespace["migrate"]()
            if result is False:
                raise RuntimeError(filename + ": migrate() gab False zurueck")
        elif "main" in namespace and callable(namespace["main"]):
            namespace["main"]()
        else:
            raise RuntimeError(filename + ": weder migrate() noch main() gefunden")
    finally:
        app_package.create_app = original_create_app


def migrate() -> bool:
    print("=" * 60)
    print("Konsolidierte Migration (Legacy bis 3.0.0)")
    print("=" * 60)

    os.environ.setdefault("PRISMATEAMS_SKIP_BACKGROUND_JOBS", "1")
    os.environ["PRISMATEAMS_RUNNING_MIGRATIONS"] = "1"

    from app import create_app, db

    app = create_app(os.getenv("FLASK_ENV", "development"))
    with app.app_context():
        try:
            for filename, b64 in _EMBEDDED_STEPS:
                print("")
                print("--- " + filename + " ---")
                try:
                    _run_embedded_step(filename, b64, app)
                    print("[OK] " + filename)
                except Exception as exc:
                    print("[FEHLER] " + filename + ": " + str(exc))
                    traceback.print_exc()
                    db.session.rollback()
                    return False

            print("")
            print("=" * 60)
            print("[OK] " + str(len(_EMBEDDED_STEPS)) + " Legacy-Migrationen abgeschlossen")
            print("=" * 60)
            return True
        finally:
            os.environ.pop("PRISMATEAMS_RUNNING_MIGRATIONS", None)


if __name__ == "__main__":
    ok = migrate()
    sys.exit(0 if ok else 1)
